STAMP=re.compile(r"(\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d)(?:\.(\d{1,9}))?(Z|[+-]\d\d:\d\d)")
def stamp(value):
    if not isinstance(value,str): raise ValueError("timestamp must be a string")
    m=STAMP.fullmatch(value)
    if not m: raise ValueError("RFC3339 seconds and up to nine fractional digits required")
    if m[3]!="Z" and (int(m[3][1:3])>23 or int(m[3][4:6])>59): raise ValueError("invalid timezone offset")
    try:
        d=datetime.datetime.fromisoformat(m[1]+("+00:00" if m[3]=="Z" else m[3])).astimezone(UTC)
    except (ValueError,OverflowError) as exc: raise ValueError("invalid date") from exc
    nanos=(m[2] or "").ljust(9,"0")
    return f"{d.year:04d}-{d.month:02d}-{d.day:02d}T{d.hour:02d}:{d.minute:02d}:{d.second:02d}."+nanos+"Z"
def digest(value):
    return hashlib.sha256(json.dumps(value,ensure_ascii=False,sort_keys=True,separators=(",",":")).encode()).hexdigest()
def apply(state,payload,source_id):
    if not isinstance(source_id,str) or not source_id: raise ValueError("trusted source identity required")
    if not isinstance(payload,dict) or payload.get("version")!="4": raise ValueError("webhook v4 required")
    if type(payload.get("truncatedAlerts",0)) is not int or payload.get("truncatedAlerts",0)!=0: raise ValueError("incomplete notification")
    if not isinstance(payload.get("alerts"),list): raise ValueError("alerts array required")
    parsed=[]
    for alert in payload["alerts"]:
        if not isinstance(alert,dict): raise ValueError("alert object required")
        labels=alert.get("labels")
        if not isinstance(labels,dict) or not labels or any(not isinstance(k,str) or not k or not isinstance(v,str) for k,v in labels.items()): raise ValueError("nonempty string label map required")
        status=alert.get("status")
        if status not in ("firing","resolved"): raise ValueError("invalid per-alert status")
        start=stamp(alert.get("startsAt"))
        end=stamp(alert.get("endsAt")) if status=="resolved" else None
        if end is not None and end<start: raise ValueError("recovery predates start")
        series=digest([source_id,labels]);incident=digest([source_id,labels,start])
        parsed.append((series,incident,copy.deepcopy(labels),status,start,end))
    if not isinstance(state,dict) or type(state.get("version")) is not int or state.get("version")!=1: raise ValueError("state v1 required")
    result=copy.deepcopy(state);actions=[]
    for series,ident,labels,status,start,end in parsed:
        current=result["incidents"].get(ident)
        if current is None:
            current={"series":series,"source":source_id,"labels":labels,"startsAt":start,"endsAt":end,"status":status}
            result["incidents"][ident]=current
            action="open" if status=="firing" else None
        elif current["status"]=="resolved":
            action=None
        elif status=="resolved":
            current["status"]="resolved";current["endsAt"]=end;action="close"
        else:
            action=None
        previous=result["latest"].get(series)
        if previous is None or result["incidents"][previous]["startsAt"]<start:
            result["latest"][series]=ident
        if action:
            action_id=ident+":"+action
            item={"id":action_id,"incident":ident,"action":action}
            if action_id not in result["outbox"]:
                result["outbox"][action_id]=item;actions.append(copy.deepcopy(item))
